  {
    variants: {
      variant: {
        primary:
          "bg-[--color-primary] text-[--color-primary-fg] hover:bg-[--color-primary-hover]",
        secondary:
          "bg-[--color-surface-2] text-[--color-text] hover:bg-[--color-surface-3]",
        destructive:
